export const UPLOAD_COMPRESSED_LIMIT=1024*1024, UPLOAD_EXPANDED_LIMIT=8*1024*1024;
const sha=async data=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',data))].map(x=>x.toString(16).padStart(2,'0')).join('');
const zip=async data=>new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
const unzip=async(data,max)=>{const reader=new Blob([data]).stream().pipeThrough(new DecompressionStream('gzip')).getReader();let n=0;const parts=[];try{while(true){const {done,value}=await reader.read();if(done)break;n+=value.length;if(n>max){await reader.cancel();throw new Error('Local chunk exceeds expanded size.');}parts.push(value);}}finally{reader.releaseLock();}const bytes=new Uint8Array(n);let i=0;for(const part of parts){bytes.set(part,i);i+=part.length;}return bytes;};
const concat=parts=>{const bytes=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let i=0;for(const part of parts){bytes.set(part,i);i+=part.length;}return bytes;};
export async function makeUploadGroups(localChunks,load){const groups=[];let start=0;while(start<localChunks.length){const parts=[];let expanded=0,end=start;while(end<localChunks.length&&expanded+localChunks[end].expandedBytes<=UPLOAD_EXPANDED_LIMIT){const meta=localChunks[end],original=await load(meta.index);if(!original||await sha(original)!==meta.sha256)throw new Error('Local chunk checksum differs; export the recording before retrying.');const plain=await unzip(original,meta.expandedBytes);if(plain.length!==meta.expandedBytes)throw new Error('Local chunk expanded size differs.');parts.push(plain);expanded+=plain.length;end++;}if(end===start)throw new Error('One local chunk exceeds upload limits.');let packed=await zip(concat(parts));if(packed.length>UPLOAD_COMPRESSED_LIMIT){let lo=1,hi=parts.length-1,best=null,bestEnd=0;while(lo<=hi){const mid=(lo+hi)>>1,candidate=await zip(concat(parts.slice(0,mid)));if(candidate.length<=UPLOAD_COMPRESSED_LIMIT){best=candidate;bestEnd=mid;lo=mid+1;}else hi=mid-1;}if(!best)throw new Error('One local chunk exceeds upload limits.');packed=best;end=start+bestEnd;expanded=parts.slice(0,bestEnd).reduce((n,p)=>n+p.length,0);}const events=localChunks.slice(start,end).reduce((n,c)=>n+c.eventCount,0);groups.push({index:groups.length,localStart:start,localEnd:end,sha256:await sha(packed),compressedBytes:packed.length,expandedBytes:expanded,eventCount:events});start=end;}return groups;}
export async function materializeGroup(group,localChunks,load){const parts=[];for(let i=group.localStart;i<group.localEnd;i++){const meta=localChunks[i],original=await load(meta.index);if(!original||await sha(original)!==meta.sha256)throw new Error('Local chunk changed during upload.');parts.push(await unzip(original,meta.expandedBytes));}const packed=await zip(concat(parts));if(packed.length!==group.compressedBytes||await sha(packed)!==group.sha256)throw new Error('Packed chunk changed; upload plan must be rebuilt with a new upload ID.');return packed;}
export function uploadManifest(local,session){return {recordingId:session.id,formatVersion:local.formatVersion,appVersion:local.appVersion,buildId:local.buildId,roadDataVersion:local.roadDataVersion,configuration:local.configuration,startedAt:local.startedAt,endedAt:local.endedAt,issue:session.issue,eventCount:local.eventCount,chunks:session.groups.map(({index,sha256,compressedBytes,expandedBytes,eventCount})=>({index,sha256,compressedBytes,expandedBytes,eventCount}))};}
export async function fetchBounded(url,options={},onRetry=()=>{}){let last;for(let attempt=1;attempt<=3;attempt++){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(url,{...options,signal:controller.signal});const bytes=new Uint8Array(await response.arrayBuffer());clearTimeout(timer);if(response.ok)return response.status===204?null:JSON.parse(new TextDecoder().decode(bytes));if([401,403,404,409,413,415,422].includes(response.status))throw new Error(`Upload rejected (${response.status}); local recording remains.`);if(response.status!==429&&response.status<500)throw new Error(`Upload failed (${response.status}); local recording remains.`);last=new Error(`Upload temporarily unavailable (${response.status}).`);let retryAfter=Number(response.headers.get('Retry-After'));if(Number.isNaN(retryAfter))retryAfter=(Date.parse(response.headers.get('Retry-After'))-Date.now())/1000;if(response.status===429&&(!Number.isFinite(retryAfter)||retryAfter>60))throw new Error('Upload rate limited; retry later.');if(attempt===3)break;onRetry(attempt);await new Promise(resolve=>setTimeout(resolve,response.status===429?Math.max(0,retryAfter)*1000:Math.min(4000,500*2**(attempt-1))));}catch(error){clearTimeout(timer);if(/Upload rejected|Upload failed|Upload rate limited/.test(error.message))throw error;last=error;if(attempt===3)break;onRetry(attempt);await new Promise(resolve=>setTimeout(resolve,Math.min(4000,500*2**(attempt-1))));}}throw new Error(`Upload interrupted: ${last?.message||'network error'}. Retry later; local recording remains.`);}
